async function exportMp4(){
  const [w,h]=outSize(), cfg=await pickMp4Config(w,h); if(!cfg) return toast("このブラウザは MP4 の書き出しに対応していません（ロスレスMOVを使ってください）");
  const N=Math.max(1,Math.round(totalDur()*FPS)), s=beginSession();
  setBusy(true,"rec"); $("rec").classList.add("rec");
  const samples=[]; let desc=null, encErr=null;
  const encoder=new VideoEncoder({ output:(chunk,m)=>{ if(!desc&&m&&m.decoderConfig&&m.decoderConfig.description) desc=new Uint8Array(m.decoderConfig.description); const b=new Uint8Array(chunk.byteLength); chunk.copyTo(b); samples.push({data:b,key:chunk.type==="key",ts:chunk.timestamp}); }, error:e=>{ encErr=e; } });
  try{
    encoder.configure(cfg);
    for(let i=0;i<N;i++){
      if(s.stop||encErr) break;
      playhead=i/FPS; await seekScenesExact(playhead); render(playhead,1,opaqueMode()); syncBar();
      const frame=new VideoFrame(view,{timestamp:Math.round(i*1e6/FPS),duration:Math.round(1e6/FPS),alpha:"discard"});
      encoder.encode(frame,{keyFrame:i%(FPS*2)===0}); frame.close();
      while(encoder.encodeQueueSize>6) await new Promise(r=>setTimeout(r,2));
      $("rec").textContent=`■ MP4 書き出し中 ${i+1}/${N}`;
      if(i%4===0) await new Promise(r=>setTimeout(r,0));
    }
    await encoder.flush(); encoder.close();
    if(encErr) throw encErr;
    if(s.stop) toast("書き出しを中止しました");
    else{ if(!desc||!samples.length) throw new Error("エンコード結果が空でした"); const blob=makeMp4(samples,desc,w,h,FPS);
