async function exportMp4() {
  if (EX.on) { EX.stop = true; return; }
  if (!window.gsap) { toast('アニメーションの読み込みに失敗しているため書き出せません'); return; }
  const cfg = await pickMp4Config(W, H, FPS);
  let mime = null;
  if (!cfg) {
    mime = window.MediaRecorder && ['video/mp4;codecs=avc1.640028', 'video/mp4', 'video/webm;codecs=vp9', 'video/webm'].find((m) => MediaRecorder.isTypeSupported(m));
    if (!mime || !cv.captureStream) { toast('このブラウザでは動画を書き出せません（Chrome / Edge を使ってください）'); return; }
  }
  if (clip.readyState < 1) await new Promise((r) => { clip.addEventListener('loadedmetadata', r, { once: true }); setTimeout(r, 4000); });
  // frame-exact seeking needs a seekable source; servers without range requests give none → load the clip into memory once
  if (!clip.src.startsWith('blob:') && !(clip.seekable.length && clip.seekable.end(0) >= clip.duration - 0.05)) {
    exBtn.textContent = '映像を読み込み中…';
    try {
      const blob = await (await fetch(clip.currentSrc)).blob();
      const ready = new Promise((r) => { clip.addEventListener('loadeddata', r, { once: true }); setTimeout(r, 8000); });
      clip.src = URL.createObjectURL(blob); clip.load(); await ready;
    } catch (e) { toast('映像を読み込めませんでした：' + ((e && e.message) || e)); exBtn.textContent = '● MP4を書き出す'; return; }
  }
  const dur = 3.4 + (Number.isFinite(clip.duration) ? clip.duration : 3.87) + 0.5;
  const N = Math.round(dur * FPS);
  Object.assign(EX, { on: true, stop: false, t: 0, tcAt: null, clipAt: null });
  exBtn.classList.add('rec');
  const g = gsap.globalTimeline; g.pause();
  boot();
  const g0 = mt.startTime();
  const samples = []; let desc = null, encErr = null, encoder = null, rec = null, track = null, chunks = [], stopped = null;
  if (cfg) {
    encoder = new VideoEncoder({ output: (chunk, meta) => { if (!desc && meta && meta.decoderConfig && meta.decoderConfig.description) desc = new Uint8Array(meta.decoderConfig.description); const b = new Uint8Array(chunk.byteLength); chunk.copyTo(b); samples.push({ data: b, key: chunk.type === 'key', ts: chunk.timestamp }); }, error: (e) => { encErr = e; } });
    encoder.configure(cfg);
  } else {
    const stream = cv.captureStream(0); track = stream.getVideoTracks()[0];
    rec = new MediaRecorder(stream, { mimeType: mime, videoBitsPerSecond: 24e6 });
    rec.ondataavailable = (e) => { if (e.data && e.data.size) chunks.push(e.data); };
    stopped = new Promise((r) => (rec.onstop = r)); rec.start(200);
  }
  const tStart = performance.now();
  let ok = true;
  try {
    for (let i = 0; i < N; i++) {
      if (EX.stop) { ok = false; break; }
      await stepTo(g0, i / FPS);
      if (encoder) {
        if (encErr) throw encErr;
        const frame = new VideoFrame(cv, { timestamp: Math.round(i * 1e6 / FPS), duration: Math.round(1e6 / FPS) });
        encoder.encode(frame, { keyFrame: i % (FPS * 2) === 0 }); frame.close();
        while (encoder.encodeQueueSize > 6) await new Promise((r) => setTimeout(r, 2));
      } else {
        while (performance.now() < tStart + i * 1000 / FPS) await new Promise((r) => requestAnimationFrame(r));
        track.requestFrame && track.requestFrame();
      }
      exBtn.textContent = `■ 中止 ${i + 1}/${N}`;
      if (i % 2 === 0) await new Promise((r) => setTimeout(r, 0));
    }
  } catch (err) { ok = false; toast('書き出しに失敗しました：' + ((err && err.message) || err)); }
  try {
    if (encoder) { await encoder.flush(); encoder.close(); }
    else { if (rec.state !== 'inactive') rec.stop(); await stopped; track.stop(); }
  } catch (e) { encErr = encErr || e; }
  Object.assign(EX, { on: false, tcAt: null, clipAt: null });
  exBtn.classList.remove('rec'); exBtn.textContent = '● MP4を書き出す';
  g.resume(); play();
  if (EX.stop) { EX.stop = false; toast('書き出しを中止しました'); return; }
  if (!ok) return;
  const name = `u19-hud-sequence-${stamp()}_${FPS}fps`;
  if (encoder) {
    if (encErr || !desc || !samples.length) { toast('MP4の書き出しに失敗しました' + (encErr ? '：' + encErr.message : '')); return; }
    await saveFile(makeMp4(samples, desc, W, H, FPS), name + '.mp4');
  } else {
    const blob = new Blob(chunks, { type: mime.split(';')[0] });
    if (!blob.size) { toast('録画データが空でした'); return; }
    await saveFile(blob, name + (mime.startsWith('video/mp4') ? '.mp4' : '.webm'));
  }
}

